import React, { useState, useEffect, useRef } from 'react';

function Game() {
    const svgRef = useRef(null);
    const pathRef = useRef(null);
    const [pathLength, setPathLength] = useState(0);
    const [currentOffset, setCurrentOffset] = useState(0);
    const [targetOffset, setTargetOffset] = useState(0);

    useEffect(() => {
        if (pathRef.current) {
            const length = pathRef.current.getTotalLength();
            setPathLength(length);
            setCurrentOffset(length); // Initialize currentOffset to pathLength
            setTargetOffset(length); // Initialize targetOffset to pathLength
            pathRef.current.style.strokeDasharray = length;
            pathRef.current.style.strokeDashoffset = length;
        }

        const scroll = () => {
            if (pathLength) {
                const distance = window.scrollY;
                const totalDistance = document.documentElement.scrollHeight - window.innerHeight;
                const percentage = totalDistance > 0 ? distance / totalDistance : 0;
                const multiplier = window.innerWidth < 600 ? 1.7 : 1.17;
                setTargetOffset(pathLength - (pathLength * (multiplier * percentage)));
            }
        };

        const animate = () => {
            const difference = targetOffset - currentOffset;
            const newOffset = currentOffset + difference * 0.1;
            setCurrentOffset(newOffset);
            if (pathRef.current) {
                pathRef.current.style.strokeDashoffset = newOffset;
            }
            if (Math.abs(difference) > 0.1) {
                requestAnimationFrame(animate);
            }
        };

        const handleScroll = () => {
            scroll();
            animate();
        };

        const handleResize = () => {
            scroll();
        };

        window.addEventListener('scroll', handleScroll);
        window.addEventListener('resize', handleResize);

        return () => {
            window.removeEventListener('scroll', handleScroll);
            window.removeEventListener('resize', handleResize);
        };
    }, [targetOffset, currentOffset, pathLength]);

    return (
        <svg className="squiggle" ref={svgRef} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 500">
            <path
                ref={pathRef}
                d="M10,250 C100,10 400,490 900,250"
                stroke="black"
                strokeWidth="2"
                fill="none"
            />
        </svg>
    );
}

export default Game;
